files.lib/rotate.sh:
source lib/service.sh
rotate_journal() {
    mv "$JOURNAL_FILE" "$JOURNAL_FILE.previous"
    request_log_reopen
    gzip -f "$JOURNAL_FILE.previous"
}

files.lib/service.sh:
request_log_reopen() {
    local pid
    pid=$(cat "$JOURNAL_PID_FILE")
    kill -USR1 "$pid"
}
service_pid() {
    cat "$JOURNAL_PID_FILE"
}
